mapper.select:
select n.id, n.type, n.title, n.content, n.biz_type, n.biz_id, n.read_status, n.read_time, n.create_time from notice n where n.user_id = #{userId}
and n.read_status = #{readStatus}
order by n.create_time desc, n.id desc limit #{offset}, #{pageSize}

select

from notice
where id = #{id}
  and user_id = #{userId}
limit 1

mapper.update:
update notice
set read_status = 1,
    read_time = #{readTime},
    update_time = #{readTime},
    update_user = #{userId}
where id = #{id}
  and user_id = #{userId}
  and read_status = 0
